//! Raw `no_std` bindings to the MicroBlaze-V (`hello_world`) standalone BSP
//! (every header in `platform/microblaze_riscv_0/standalone_microblaze_riscv_0/bsp/include`), generated by
//! bindgen at build time. Linking this crate pulls in libxil, libxilstandalone and libxiltimer
//! (plus newlib's libc, libgloss and libgcc) as one link group.
//!
//! Function-like macros (`XGpio_WriteReg`, `XWdtTb_ReadReg`, `fence`, ...) and
//! `static inline` functions (`Xil_Out32`, ...) are callable under their C names
//! through small C shims compiled alongside the bindings.
#![no_std]
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]
#![allow(clippy::all, rustdoc::all, unnecessary_transmutes)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
